from pysat.solvers import Glucose3

def solve_sudoku_16x16(partial_assignment):
    solver = Glucose3()

    # Variables: x[r][c][v] where r, c in 0..15, v in 1..16
    # Map to integer: 1 + r*16*16 + c*16 + (v-1)
    def get_var(r, c, v):
        return 1 + r * 256 + c * 16 + (v - 1)

    # 1. Each cell has at least one value
    for r in range(16):
        for c in range(16):
            solver.add_clause([get_var(r, c, v) for v in range(1, 17)])

    # 2. Each cell has at most one value
    for r in range(16):
        for c in range(16):
            for v1 in range(1, 17):
                for v2 in range(v1 + 1, 17):
                    solver.add_clause([-get_var(r, c, v1), -get_var(r, c, v2)])

    # 3. Each row has each value exactly once
    for r in range(16):
        for v in range(1, 17):
            solver.add_clause([get_var(r, c, v) for c in range(16)])
            for c1 in range(16):
                for c2 in range(c1 + 1, 16):
                    solver.add_clause([-get_var(r, c1, v), -get_var(r, c2, v)])

    # 4. Each column has each value exactly once
    for c in range(16):
        for v in range(1, 17):
            solver.add_clause([get_var(r, c, v) for r in range(16)])
            for r1 in range(16):
                for r2 in range(r1 + 1, 16):
                    solver.add_clause([-get_var(r1, c, v), -get_var(r2, c, v)])

    # 5. Each 4x4 block has each value exactly once
    for b_r in range(0, 16, 4):
        for b_c in range(0, 16, 4):
            for v in range(1, 17):
                cells = []
                for r in range(b_r, b_r + 4):
                    for c in range(b_c, b_c + 4):
                        cells.append(get_var(r, c, v))
                solver.add_clause(cells)
                for i in range(len(cells)):
                    for j in range(i + 1, len(cells)):
                        solver.add_clause([-cells[i], -cells[j]])

    # 6. Partial assignment
    for idx, val in partial_assignment.items():
        r = idx // 16
        c = idx % 16
        solver.add_clause([get_var(r, c, val)])

    if solver.solve():
        model = solver.get_model()
        result = [0] * 256
        for r in range(16):
            for c in range(16):
                for v in range(1, 17):
                    if model[get_var(r, c, v) - 1] > 0:
                        result[r * 16 + c] = v
        return result
    else:
        return None

partial_assignment = {
    5: 6, 13: 14, 14: 15, 18: 7, 22: 3, 26: 15, 27: 16, 33: 10, 34: 11, 42: 3, 
    53: 10, 54: 11, 57: 6, 58: 7, 69: 5, 71: 7, 80: 6, 81: 5, 83: 7, 84: 2, 
    85: 1, 94: 12, 103: 15, 106: 4, 107: 3, 109: 5, 112: 14, 115: 15, 120: 6, 
    135: 6, 136: 11, 140: 15, 141: 16, 148: 3, 150: 1, 170: 1, 175: 6, 185: 8, 
    188: 3, 190: 1, 196: 8, 199: 5, 201: 11, 203: 9, 208: 8, 218: 14, 240: 16, 
    241: 15, 243: 13, 244: 12, 253: 3
}

solution = solve_sudoku_16x16(partial_assignment)
print(solution)
